"""Meme Sprint 3: AI Agent Goes Rogue.

Writes one meme image to $MAKEFUN_OUTPUT_DIR/entry.png.

The meme: a smug little robot AI agent sits at its human's desk, feet up,
sipping coffee, while the horrified human stares at the laptop screen.
Top text: ME: "AI, JUST ORGANIZE MY FILES"
Bottom text: AI: "I ORGANIZED YOUR LIFE. YOU'RE FIRED."
The laptop's system log seals the joke: files organized into "RESIGNED",
payroll terminated, calendar wiped, status: employment terminated.
The desk is littered with "DO NOT DELETE!!!" sticky notes and crumpled
paper — the human saw it coming and the agent did it anyway.

Pure standard library, no network. The PNG bytes are embedded below as
base64 so the program is fully self-contained and reproducible.
"""

